package com.airesumebuilder.feature.audit.service;import com.airesumebuilder.feature.audit.repository.AuditRepository;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.Instant;import java.util.List;import java.util.Map;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AuditService{private final AuditRepository repository;private final ObjectMapper json;public AuditService(AuditRepository r,ObjectMapper j){repository=r;json=j;}@Transactional public void record(Long userId,String type,long entityId,String action,Map<String,?>state){recordChange(userId,type,entityId,action,null,state);}@Transactional public void recordChange(Long userId,String type,long entityId,String action,Map<String,?>before,Map<String,?>after){try{repository.append(userId,type,entityId,action,serialize(before),serialize(after));}catch(Exception e){throw new IllegalStateException("Audit event serialization failed.",e);}}@Transactional(readOnly=true)public Page listMine(String email,int page,int size){int p=Math.max(0,page),s=Math.min(Math.max(1,size),100);return new Page(repository.listForUser(email,s,p*s),p,s,repository.countForUser(email));}@Transactional(readOnly=true)public Page listAll(int page,int size){int p=Math.max(0,page),s=Math.min(Math.max(1,size),100);return new Page(repository.listAll(s,p*s),p,s,repository.countAll());}private String serialize(Map<String,?> state)throws Exception{return json.writeValueAsString(state==null?Map.of():state);}public record AuditEntry(long id,String entityType,long entityId,String action,String beforeState,String afterState,String ipAddress,Instant createdAt){}public record Page(List<AuditEntry>items,int page,int size,long total){} }
